import { get as idbGet, set as idbSet } from "idb-keyval";
import { create } from "zustand";
import type {
  KnowledgeCard,
  KnowledgeCategoryId,
  PracticeAttempt,
  PracticeItem,
} from "@inkflow/shared";
import { createId } from "../lib/createId";
import {
  KNOWLEDGE_BOOKS,
  knowledgeBookById,
  moduleForNode,
  nodeById,
} from "../components/knowledge/knowledgeCatalog";

const STORAGE_KEY = "inkflow:knowledge-space:v1";

interface PersistedKnowledgeState {
  cards: KnowledgeCard[];
  attempts: PracticeAttempt[];
}

interface ManualCardInput {
  categoryId: KnowledgeCategoryId;
  title: string;
  summaryZh: string;
  keyPoints: string[];
  terms: string[];
  personalQuestion?: string;
  sourceLabel?: string;
}

interface KnowledgeState extends PersistedKnowledgeState {
  initialized: boolean;
  hydrate: () => Promise<void>;
  addNodeCard: (bookId: string, nodeId: string) => KnowledgeCard | null;
  addManualCard: (input: ManualCardInput) => KnowledgeCard;
  updateCard: (id: string, patch: Partial<KnowledgeCard>) => void;
  removeCard: (id: string) => void;
  setCardMastery: (
    id: string,
    mastery: KnowledgeCard["mastery"],
  ) => void;
  recordAttempt: (
    practice: PracticeItem,
    bookId: string,
    answer: string,
    correct: boolean,
  ) => void;
}

function persist(cards: KnowledgeCard[], attempts: PracticeAttempt[]) {
  if (typeof indexedDB === "undefined") return;
  void idbSet(STORAGE_KEY, { cards, attempts }).catch(() => undefined);
}

function cardExists(
  cards: KnowledgeCard[],
  bookId: string,
  nodeId: string,
) {
  return cards.some(
    (card) =>
      card.source === "node" &&
      card.bookId === bookId &&
      card.nodeId === nodeId,
  );
}

export const useKnowledge = create<KnowledgeState>((set, get) => ({
  initialized: false,
  cards: [],
  attempts: [],

  async hydrate() {
    if (get().initialized) return;
    const stored = await idbGet<PersistedKnowledgeState>(STORAGE_KEY).catch(
      () => undefined,
    );
    set({
      cards: stored?.cards ?? [],
      attempts: stored?.attempts ?? [],
      initialized: true,
    });
  },

  addNodeCard(bookId, nodeId) {
    if (cardExists(get().cards, bookId, nodeId)) return null;
    const book = knowledgeBookById(bookId);
    const currentNode = book ? nodeById(book, nodeId) : undefined;
    const module = book ? moduleForNode(book, nodeId) : undefined;
    if (!book || !currentNode) return null;
    const now = new Date().toISOString();
    const card: KnowledgeCard = {
      id: `knowledge-card-${createId()}`,
      source: "node",
      categoryId: book.categoryId,
      bookId,
      moduleId: module?.id,
      nodeId,
      title: currentNode.title,
      summaryZh: currentNode.summaryZh,
      keyPoints: currentNode.keyPoints,
      terms: currentNode.terms,
      personalQuestion: "",
      sourceLabel: currentNode.sourceRef?.sourceLabel ?? book.title,
      sourceQuote: currentNode.sourceRef?.quote ?? "",
      color: "yellow",
      mastery: "new",
      createdAt: now,
      updatedAt: now,
    };
    const cards = [card, ...get().cards];
    set({ cards });
    persist(cards, get().attempts);
    return card;
  },

  addManualCard(input) {
    const now = new Date().toISOString();
    const card: KnowledgeCard = {
      id: `knowledge-card-${createId()}`,
      source: "manual",
      categoryId: input.categoryId,
      title: input.title.trim().slice(0, 120),
      summaryZh: input.summaryZh.trim().slice(0, 800),
      keyPoints: input.keyPoints.filter(Boolean).slice(0, 12),
      terms: input.terms.filter(Boolean).slice(0, 24),
      personalQuestion: input.personalQuestion?.trim() ?? "",
      sourceLabel: input.sourceLabel?.trim() ?? "My knowledge card",
      sourceQuote: "",
      color: "blue",
      mastery: "new",
      createdAt: now,
      updatedAt: now,
    };
    const cards = [card, ...get().cards];
    set({ cards });
    persist(cards, get().attempts);
    return card;
  },

  updateCard(id, patch) {
    const cards = get().cards.map((card) =>
      card.id === id
        ? { ...card, ...patch, updatedAt: new Date().toISOString() }
        : card,
    );
    set({ cards });
    persist(cards, get().attempts);
  },

  removeCard(id) {
    const cards = get().cards.filter((card) => card.id !== id);
    set({ cards });
    persist(cards, get().attempts);
  },

  setCardMastery(id, mastery) {
    get().updateCard(id, { mastery });
  },

  recordAttempt(practice, bookId, answer, correct) {
    const attempt: PracticeAttempt = {
      id: `attempt-${createId()}`,
      practiceId: practice.id,
      nodeId: practice.nodeId,
      bookId,
      answer,
      correct,
      at: new Date().toISOString(),
    };
    const attempts = [...get().attempts, attempt].slice(-1000);
    set({ attempts });
    persist(get().cards, attempts);
    if (!correct) get().addNodeCard(bookId, practice.nodeId);
  },
}));

export function knowledgeAttemptsForBook(
  attempts: PracticeAttempt[],
  bookId: string,
) {
  return attempts.filter((attempt) => attempt.bookId === bookId);
}

export function knowledgeMasteryByBook(
  cards: KnowledgeCard[],
  bookId: string,
) {
  const book = knowledgeBookById(bookId);
  if (!book) return 0;
  const nodeIds = new Set(book.modules.flatMap((module) => module.nodes.map((node) => node.id)));
  const mastered = cards.filter(
    (card) =>
      card.bookId === bookId &&
      card.nodeId &&
      nodeIds.has(card.nodeId) &&
      card.mastery === "mastered",
  ).length;
  return nodeIds.size ? Math.round((mastered / nodeIds.size) * 100) : 0;
}

export function totalKnowledgeNodes() {
  return KNOWLEDGE_BOOKS.reduce(
    (total, book) =>
      total +
      book.modules.reduce((sum, module) => sum + module.nodes.length, 0),
    0,
  );
}
