function practice(
  id: string,
  nodeId: string,
  kind: PracticeItem["kind"],
  prompt: string,
  answer: string,
  explanationZh: string,
  options: string[] = [],
): PracticeItem {
  return {
    id,
    nodeId,
    kind,
    prompt,
    options,
    answer,
    acceptedAnswers: [answer],
    explanationZh,
    difficulty: 2,
  };
}

function node(
  value: KnowledgeNode,
): KnowledgeNode {
  return value;
}

