export function knowledgeBookById(id: string | undefined) {
  return KNOWLEDGE_BOOKS.find((book) => book.id === id);
}

export function knowledgeBooksByCategory(categoryId: string | undefined) {
  if (!categoryId) return KNOWLEDGE_BOOKS;
  return KNOWLEDGE_BOOKS.filter((book) => book.categoryId === categoryId);
}

export function knowledgeCategoryById(id: string | undefined) {
  return KNOWLEDGE_CATEGORIES.find((category) => category.id === id);
}

export function nodesForBook(book: KnowledgeBook) {
  return book.modules.flatMap((module) => module.nodes);
}

export function practiceForBook(book: KnowledgeBook) {
  return nodesForBook(book).flatMap((item) => item.practice);
}

export function moduleForNode(book: KnowledgeBook, nodeId: string) {
  return book.modules.find((module) =>
    module.nodes.some((item) => item.id === nodeId),
  );
}

export function nodeById(book: KnowledgeBook, nodeId: string) {
  return nodesForBook(book).find((item) => item.id === nodeId);
}
